import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);String s1=sc.next(),s2=sc.next();int m=s1.length(),n=s2.length();if(m>n){System.out.println("No");return;}int[]need=new int[26],win=new int[26];int matched=0;for(int i=0;i<m;i++){need[s1.charAt(i)-'a']++;win[s2.charAt(i)-'a']++;}for(int i=0;i<26;i++)if(win[i]==need[i])matched++;if(matched==26){System.out.println("Yes");return;}for(int i=m;i<n;i++){int in=s2.charAt(i)-'a',out=s2.charAt(i-m)-'a';if(win[in]==need[in])matched--;win[in]++;if(win[in]==need[in])matched++;if(win[out]==need[out])matched--;win[out]--;if(win[out]==need[out])matched++;if(matched==26){System.out.println("Yes");return;}}System.out.println("No");}}
